class PromotionCatalog {
    // Tham chiếu tới một ảnh chụp bất biến; thay cả ảnh chụp, không sửa tại chỗ
    private volatile List<Promotion> active = List.of();

    List<Promotion> activePromotions() {
        return active;
    }

    @Scheduled(fixedRate = 60_000)
    void refresh() {
        active = List.copyOf(promotionClient.fetchActive());
    }
}
